package com.citacloud.app.services; import com.citacloud.app.models.ConfiguracionEmpresaFase2; import com.citacloud.app.repositories.ConfiguracionEmpresaFase2Repository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ConfiguracionFase2Service {private final ConfiguracionEmpresaFase2Repository repo;public ConfiguracionFase2Service(ConfiguracionEmpresaFase2Repository r){repo=r;}public ConfiguracionEmpresaFase2 obtener(UUID empresa){return repo.findById(empresa).orElseGet(()->{ConfiguracionEmpresaFase2 c=new ConfiguracionEmpresaFase2();c.setEmpresaId(empresa);return c;});}public ConfiguracionEmpresaFase2 guardar(UUID e,boolean requiere,String prefijo,int siguiente,boolean recordatorios){if(e==null)throw new IllegalArgumentException("No se pudo identificar la empresa.");String prefijoSeguro=prefijo==null||prefijo.isBlank()?"FAC":prefijo.trim().toUpperCase();int siguienteSeguro=siguiente<1?1:siguiente;ConfiguracionEmpresaFase2 c=obtener(e);c.setRequiereAprobacionCitas(requiere);c.setPrefijoFactura(prefijoSeguro);c.setSiguienteFactura(siguienteSeguro);c.setRecordatoriosActivos(recordatorios);return repo.save(c);}}
